INSERT INTO `projects_i18n` (`id`, `project_id`, `locale`, `title`, `slug`, `summary`, `content`, `featured_image_alt`, `meta_title`, `meta_description`, `created_at`, `updated_at`) VALUES
  ('40000001-0000-4000-8000-000000000001', '40000000-0000-4000-8000-000000000001', 'tr', 'Çok Dilli B2B Sitesi — GEO + SEO + Lighthouse Analizi', 'cok-dilli-b2b-sitesi-geo-seo-lighthouse-analizi', 'Çok dilli B2B ihracat sitesi olusturuldu. GEO + SEO + Lighthouse analizi: AI arama motorlarına (ChatGPT, Perplexity, Gemini) yönelik GEO, teknik SEO (hreflang, sitemap, schema) ve Core Web Vitals performans raporu. Aksiyon planıyla teslim edildi.', '{"html":"<p>Çok dilli B2B ihracat sitesi olusturuldu. GEO + SEO + Lighthouse analizi: AI arama motorlarına (ChatGPT, Perplexity, Gemini) yönelik GEO, teknik SEO (hreflang, sitemap, schema) ve Core Web Vitals performans raporu. Aksiyon planıyla teslim edildi.</p>","description":"Çok dilli B2B ihracat sitesi olusturuldu. GEO + SEO + Lighthouse analizi: AI arama motorlarına (ChatGPT, Perplexity, Gemini) yönelik GEO, teknik SEO (hreflang, sitemap, schema) ve Core Web Vitals performans raporu. Aksiyon planıyla teslim edildi.","key_features":["Diğer Yazılım Teknoloji","Admin panel ve yönetilebilir içerik","SEO/GEO uyumlu yapı"],"technologies_used":["Next.js","Fastify","MySQL"],"design_highlights":["Responsive arayüz","Performans odaklı kurulum"]}', 'Çok Dilli B2B Sitesi — GEO + SEO + Lighthouse Analizi', 'Çok Dilli B2B Sitesi — GEO + SEO + Lighthouse Analizi | GZL Teknoloji', 'Çok dilli B2B ihracat sitesi olusturuldu. GEO + SEO + Lighthouse analizi: AI arama motorlarına (ChatGPT, Perplexity, Gemini) yönelik GEO, teknik SEO (hreflang, sitemap, schema) ve Core Web Vitals performans raporu. Aksiyon planıyla teslim edildi.', '2026-06-11 20:51:13.000', '2026-06-11 20:51:13.000'),
  ('40000001-0000-4000-8000-000000000002', '40000000-0000-4000-8000-000000000002', 'tr', 'TrackPulse — Web Analitik & Dönüşüm İzleme Platformu', 'trackpulse-web-analitik-donusum-izleme-platformu', 'GA4, Google Tag Manager, Meta Pixel ve Google Ads dönüşüm izleme kurulumu yapan ve tüm kaynakları tek panelde birleştiren web analitik platformu. Olay/dönüşüm takibi, dönüşüm hunisi, kanal/atıf (ROAS) analizi ve server-side tracking kurulumu.', '{"html":"<p>GA4, Google Tag Manager, Meta Pixel ve Google Ads dönüşüm izleme kurulumu yapan ve tüm kaynakları tek panelde birleştiren web analitik platformu. Olay/dönüşüm takibi, dönüşüm hunisi, kanal/atıf (ROAS) analizi ve server-side tracking kurulumu.</p>","description":"GA4, Google Tag Manager, Meta Pixel ve Google Ads dönüşüm izleme kurulumu yapan ve tüm kaynakları tek panelde birleştiren web analitik platformu. Olay/dönüşüm takibi, dönüşüm hunisi, kanal/atıf (ROAS) analizi ve server-side tracking kurulumu.","key_features":["Web Analytics & İzleme","Admin panel ve yönetilebilir içerik","SEO/GEO uyumlu yapı"],"technologies_used":["Next.js","Fastify","MySQL"],"design_highlights":["Responsive arayüz","Performans odaklı kurulum"]}', 'TrackPulse — Web Analitik & Dönüşüm İzleme Platformu', 'TrackPulse — Web Analitik & Dönüşüm İzleme Platformu | GZL Teknoloji', 'GA4, Google Tag Manager, Meta Pixel ve Google Ads dönüşüm izleme kurulumu yapan ve tüm kaynakları tek panelde birleştiren web analitik platformu. Olay/dönüşüm takibi, dönüşüm hunisi, kanal/atıf (ROAS) analizi ve server-side tracking kurulumu.', '2026-06-11 20:51:13.000', '2026-06-11 20:51:13.000'),
  ('40000001-0000-4000-8000-000000000003', '40000000-0000-4000-8000-000000000003', 'tr', 'GeoSerra — Yapay Zeka Aramaları İçin GEO + SEO Platformu', 'geoserra-yapay-zeka-aramalari-icin-geo-seo-platformu', 'ChatGPT, Perplexity, Gemini ve Google AI Overviews için siteleri analiz edip optimize eden GEO + SEO platformu. 6 boyutlu GEO skoru, AI crawler erişimi, citability, schema/llms.txt denetimi, PDF rapor ve aksiyon planı. Next.js + Fastify + Python.', '{"html":"<p>ChatGPT, Perplexity, Gemini ve Google AI Overviews için siteleri analiz edip optimize eden GEO + SEO platformu. 6 boyutlu GEO skoru, AI crawler erişimi, citability, schema/llms.txt denetimi, PDF rapor ve aksiyon planı. Next.js + Fastify + Python.</p>","description":"ChatGPT, Perplexity, Gemini ve Google AI Overviews için siteleri analiz edip optimize eden GEO + SEO platformu. 6 boyutlu GEO skoru, AI crawler erişimi, citability, schema/llms.txt denetimi, PDF rapor ve aksiyon planı. Next.js + Fastify + Python.","key_features":["Diğer İnternet Reklamcılığı","Admin panel ve yönetilebilir içerik","SEO/GEO uyumlu yapı"],"technologies_used":["Next.js","Fastify","MySQL"],"design_highlights":["Responsive arayüz","Performans odaklı kurulum"]}', 'GeoSerra — Yapay Zeka Aramaları İçin GEO + SEO Platformu', 'GeoSerra — Yapay Zeka Aramaları İçin GEO + SEO Platformu | GZL Teknoloji', 'ChatGPT, Perplexity, Gemini ve Google AI Overviews için siteleri analiz edip optimize eden GEO + SEO platformu. 6 boyutlu GEO skoru, AI crawler erişimi, citability, schema/llms.txt denetimi, PDF rapor ve aksiyon planı. Next.js + Fastify + Python.', '2026-06-11 20:51:13.000', '2026-06-11 20:51:13.000'),
  ('40000001-0000-4000-8000-000000000004', '40000000-0000-4000-8000-000000000004', 'tr', 'Amozon — Amazon Ticari Radar & AI Karar Motoru', 'amozon-amazon-ticari-radar-ai-karar-motoru', 'Amazon kategorilerinde keyword/ASIN tarayıp 5 boyutlu risk skoru ve LLM reasoning ile açıklanabilir AL/TAKİP_ET/UZAK_DUR kararı üreten ticari radar. Oxylabs scraping + Keepa fiyat geçmişi + tez izleme. TypeScript/Bun + Next.js + MySQL.', '{"html":"<p>Amazon kategorilerinde keyword/ASIN tarayıp 5 boyutlu risk skoru ve LLM reasoning ile açıklanabilir AL/TAKİP_ET/UZAK_DUR kararı üreten ticari radar. Oxylabs scraping + Keepa fiyat geçmişi + tez izleme. TypeScript/Bun + Next.js + MySQL.</p>","description":"Amazon kategorilerinde keyword/ASIN tarayıp 5 boyutlu risk skoru ve LLM reasoning ile açıklanabilir AL/TAKİP_ET/UZAK_DUR kararı üreten ticari radar. Oxylabs scraping + Keepa fiyat geçmişi + tez izleme. TypeScript/Bun + Next.js + MySQL.","key_features":["Pazar Araştırmaları","Admin panel ve yönetilebilir içerik","SEO/GEO uyumlu yapı"],"technologies_used":["Next.js","Fastify","MySQL"],"design_highlights":["Responsive arayüz","Performans odaklı kurulum"]}', 'Amozon — Amazon Ticari Radar & AI Karar Motoru', 'Amozon — Amazon Ticari Radar & AI Karar Motoru | GZL Teknoloji', 'Amazon kategorilerinde keyword/ASIN tarayıp 5 boyutlu risk skoru ve LLM reasoning ile açıklanabilir AL/TAKİP_ET/UZAK_DUR kararı üreten ticari radar. Oxylabs scraping + Keepa fiyat geçmişi + tez izleme. TypeScript/Bun + Next.js + MySQL.', '2026-06-11 20:51:13.000', '2026-06-11 20:51:13.000'),
  ('40000001-0000-4000-8000-000000000005', '40000000-0000-4000-8000-000000000005', 'tr', 'GenomAI — Genomik Tahmin & AI Bitki Islahı Platformu', 'genomai-genomik-tahmin-ai-bitki-islahi-platformu', 'Bitki ıslahını genomik tahmin (GEBV), GWAS marker analizi ve AI çaprazlama önerisiyle dijitalleştiren bilimsel Ar-Ge platformu. 8-12 yıllık tarla denemelerini haftalara indirir. Fastify + Python ML (scikit-learn, sommer R) + MLflow + Next.js.', '{"html":"<p>Bitki ıslahını genomik tahmin (GEBV), GWAS marker analizi ve AI çaprazlama önerisiyle dijitalleştiren bilimsel Ar-Ge platformu. 8-12 yıllık tarla denemelerini haftalara indirir. Fastify + Python ML (scikit-learn, sommer R) + MLflow + Next.js.</p>","description":"Bitki ıslahını genomik tahmin (GEBV), GWAS marker analizi ve AI çaprazlama önerisiyle dijitalleştiren bilimsel Ar-Ge platformu. 8-12 yıllık tarla denemelerini haftalara indirir. Fastify + Python ML (scikit-learn, sommer R) + MLflow + Next.js.","key_features":["Data Analizi & Raporlama","Admin panel ve yönetilebilir içerik","SEO/GEO uyumlu yapı"],"technologies_used":["Next.js","Fastify","MySQL"],"design_highlights":["Responsive arayüz","Performans odaklı kurulum"]}', 'GenomAI — Genomik Tahmin & AI Bitki Islahı Platformu', 'GenomAI — Genomik Tahmin & AI Bitki Islahı Platformu | GZL Teknoloji', 'Bitki ıslahını genomik tahmin (GEBV), GWAS marker analizi ve AI çaprazlama önerisiyle dijitalleştiren bilimsel Ar-Ge platformu. 8-12 yıllık tarla denemelerini haftalara indirir. Fastify + Python ML (scikit-learn, sommer R) + MLflow + Next.js.', '2026-06-11 20:51:13.000', '2026-06-11 20:51:13.000'),
  ('40000001-0000-4000-8000-000000000006', '40000000-0000-4000-8000-000000000006', 'tr', 'SocialPulse — Sosyal Medya Yönetim & Otomasyon Platformu', 'socialpulse-sosyal-medya-yonetim-otomasyon-platformu', 'Kişiye özel, çok platformlu sosyal medya yönetim ve otomasyon SaaS''ı. Instagram, Facebook, X, YouTube, LinkedIn ve reklamlar için zamanlanmış yayın, içerik takvimi, AI içerik üretimi ve GA4/Ads analitiği. Next.js 16 + Fastify + MySQL.', '{"html":"<p>Kişiye özel, çok platformlu sosyal medya yönetim ve otomasyon SaaS''ı. Instagram, Facebook, X, YouTube, LinkedIn ve reklamlar için zamanlanmış yayın, içerik takvimi, AI içerik üretimi ve GA4/Ads analitiği. Next.js 16 + Fastify + MySQL.</p>","description":"Kişiye özel, çok platformlu sosyal medya yönetim ve otomasyon SaaS''ı. Instagram, Facebook, X, YouTube, LinkedIn ve reklamlar için zamanlanmış yayın, içerik takvimi, AI içerik üretimi ve GA4/Ads analitiği. Next.js 16 + Fastify + MySQL.","key_features":["Sosyal Medya Yönetimi","Admin panel ve yönetilebilir içerik","SEO/GEO uyumlu yapı"],"technologies_used":["Next.js","Fastify","MySQL"],"design_highlights":["Responsive arayüz","Performans odaklı kurulum"]}', 'SocialPulse — Sosyal Medya Yönetim & Otomasyon Platformu', 'SocialPulse — Sosyal Medya Yönetim & Otomasyon Platformu | GZL Teknoloji', 'Kişiye özel, çok platformlu sosyal medya yönetim ve otomasyon SaaS''ı. Instagram, Facebook, X, YouTube, LinkedIn ve reklamlar için zamanlanmış yayın, içerik takvimi, AI içerik üretimi ve GA4/Ads analitiği. Next.js 16 + Fastify + MySQL.', '2026-06-11 20:51:13.000', '2026-06-11 20:51:13.000'),
  ('40000001-0000-4000-8000-000000000007', '40000000-0000-4000-8000-000000000007', 'tr', 'MarketPulse — Bayi, Rakip & Pazar İzleme SaaS Platformu', 'marketpulse-bayi-rakip-pazar-izleme-saas-platformu', 'Türk KOBİ ve sanayi firmaları için scraper destekli B2B intelligence SaaS''ı. Amazon, dizin ve fuar taramasından lead üretimi, otomatik churn risk skoru, rakip & pazar sinyali takibi, AI outreach ve haftalık PDF raporu. Next.js 16 + Fastify + Python.', '{"html":"<p>Türk KOBİ ve sanayi firmaları için scraper destekli B2B intelligence SaaS''ı. Amazon, dizin ve fuar taramasından lead üretimi, otomatik churn risk skoru, rakip & pazar sinyali takibi, AI outreach ve haftalık PDF raporu. Next.js 16 + Fastify + Python.</p>","description":"Türk KOBİ ve sanayi firmaları için scraper destekli B2B intelligence SaaS''ı. Amazon, dizin ve fuar taramasından lead üretimi, otomatik churn risk skoru, rakip & pazar sinyali takibi, AI outreach ve haftalık PDF raporu. Next.js 16 + Fastify + Python.","key_features":["Satış & Müşteri Bulma","Admin panel ve yönetilebilir içerik","SEO/GEO uyumlu yapı"],"technologies_used":["Next.js","Fastify","MySQL"],"design_highlights":["Responsive arayüz","Performans odaklı kurulum"]}', 'MarketPulse — Bayi, Rakip & Pazar İzleme SaaS Platformu', 'MarketPulse — Bayi, Rakip & Pazar İzleme SaaS Platformu | GZL Teknoloji', 'Türk KOBİ ve sanayi firmaları için scraper destekli B2B intelligence SaaS''ı. Amazon, dizin ve fuar taramasından lead üretimi, otomatik churn risk skoru, rakip & pazar sinyali takibi, AI outreach ve haftalık PDF raporu. Next.js 16 + Fastify + Python.', '2026-06-11 20:51:13.000', '2026-06-11 20:51:13.000'),
  ('40000001-0000-4000-8000-000000000008', '40000000-0000-4000-8000-000000000008', 'tr', 'Paspas ERP — Üretim ve Operasyon Yönetim Sistemi', 'paspas-erp-uretim-ve-operasyon-yonetim-sistemi', 'Üretim sektörü için sıfırdan geliştirdiğim çok kullanıcılı ERP. Stok, sipariş, üretim planlama ve operasyon yönetimi tek panelde. Fastify + Drizzle ORM + MySQL ve Next.js yönetim paneli; rol bazlı yetki ve çok kullanıcılı veri tutarlılığı sağlandı.', '{"html":"<p>Üretim sektörü için sıfırdan geliştirdiğim çok kullanıcılı ERP. Stok, sipariş, üretim planlama ve operasyon yönetimi tek panelde. Fastify + Drizzle ORM + MySQL ve Next.js yönetim paneli; rol bazlı yetki ve çok kullanıcılı veri tutarlılığı sağlandı.</p>","description":"Üretim sektörü için sıfırdan geliştirdiğim çok kullanıcılı ERP. Stok, sipariş, üretim planlama ve operasyon yönetimi tek panelde. Fastify + Drizzle ORM + MySQL ve Next.js yönetim paneli; rol bazlı yetki ve çok kullanıcılı veri tutarlılığı sağlandı.","key_features":["Diğer Yazılım Teknoloji","Admin panel ve yönetilebilir içerik","SEO/GEO uyumlu yapı"],"technologies_used":["Next.js","Fastify","MySQL"],"design_highlights":["Responsive arayüz","Performans odaklı kurulum"]}', 'Paspas ERP — Üretim ve Operasyon Yönetim Sistemi', 'Paspas ERP — Üretim ve Operasyon Yönetim Sistemi | GZL Teknoloji', 'Üretim sektörü için sıfırdan geliştirdiğim çok kullanıcılı ERP. Stok, sipariş, üretim planlama ve operasyon yönetimi tek panelde. Fastify + Drizzle ORM + MySQL ve Next.js yönetim paneli; rol bazlı yetki ve çok kullanıcılı veri tutarlılığı sağlandı.', '2026-06-11 20:51:13.000', '2026-06-11 20:51:13.000'),
  ('40000001-0000-4000-8000-000000000009', '40000000-0000-4000-8000-000000000009', 'tr', 'Wiribu.de – Lighthouse 100/100 & GEO/SEO Optimizasyonu', 'wiribu-de-lighthouse-100-100-geo-seo-optimizasyonu', 'Almanya pazarına yönelik PHP haber portalında teknik SEO ve GEO optimizasyonu. Lighthouse 4 kategoride 100/100 skoruna ulaşıldı. JSON-LD şema, llms.txt, IndexNow, AI tarayıcı erişimi ve structured data iyileştirmeleri yapıldı. GEO skoru 35''ten 74''e y', '{"html":"<p>Almanya pazarına yönelik PHP haber portalında teknik SEO ve GEO optimizasyonu. Lighthouse 4 kategoride 100/100 skoruna ulaşıldı. JSON-LD şema, llms.txt, IndexNow, AI tarayıcı erişimi ve structured data iyileştirmeleri yapıldı. GEO skoru 35''ten 74''e y</p>","description":"Almanya pazarına yönelik PHP haber portalında teknik SEO ve GEO optimizasyonu. Lighthouse 4 kategoride 100/100 skoruna ulaşıldı. JSON-LD şema, llms.txt, IndexNow, AI tarayıcı erişimi ve structured data iyileştirmeleri yapıldı. GEO skoru 35''ten 74''e y","key_features":["Web Yazılım","Admin panel ve yönetilebilir içerik","SEO/GEO uyumlu yapı"],"technologies_used":["Next.js","Fastify","MySQL"],"design_highlights":["Responsive arayüz","Performans odaklı kurulum"]}', 'Wiribu.de – Lighthouse 100/100 & GEO/SEO Optimizasyonu', 'Wiribu.de – Lighthouse 100/100 & GEO/SEO Optimizasyonu | GZL Teknoloji', 'Almanya pazarına yönelik PHP haber portalında teknik SEO ve GEO optimizasyonu. Lighthouse 4 kategoride 100/100 skoruna ulaşıldı. JSON-LD şema, llms.txt, IndexNow, AI tarayıcı erişimi ve structured data iyileştirmeleri yapıldı. GEO skoru 35''ten 74''e y', '2026-06-11 20:51:13.000', '2026-06-11 20:51:13.000'),
  ('40000001-0000-4000-8000-000000000010', '40000000-0000-4000-8000-000000000010', 'tr', 'Wiribu.de – Lighthouse 100/100 & GEO Optimizasyonu', 'wiribu-de-lighthouse-100-100-geo-optimizasyonu', 'PHP haber portalında kapsamlı SEO & GEO optimizasyonu. Lighthouse 4 kategoride 100/100, GEO skoru 35→74. JSON-LD NewsArticle şeması, llms.txt, IndexNow, AI tarayıcı erişimi (%95) ve featured image alt text sistemi hayata geçirildi. Wiribu.de (Almanya', '{"html":"<p>PHP haber portalında kapsamlı SEO & GEO optimizasyonu. Lighthouse 4 kategoride 100/100, GEO skoru 35→74. JSON-LD NewsArticle şeması, llms.txt, IndexNow, AI tarayıcı erişimi (%95) ve featured image alt text sistemi hayata geçirildi. Wiribu.de (Almanya</p>","description":"PHP haber portalında kapsamlı SEO & GEO optimizasyonu. Lighthouse 4 kategoride 100/100, GEO skoru 35→74. JSON-LD NewsArticle şeması, llms.txt, IndexNow, AI tarayıcı erişimi (%95) ve featured image alt text sistemi hayata geçirildi. Wiribu.de (Almanya","key_features":["Diğer Yazılım Teknoloji","Admin panel ve yönetilebilir içerik","SEO/GEO uyumlu yapı"],"technologies_used":["Next.js","Fastify","MySQL"],"design_highlights":["Responsive arayüz","Performans odaklı kurulum"]}', 'Wiribu.de – Lighthouse 100/100 & GEO Optimizasyonu', 'Wiribu.de – Lighthouse 100/100 & GEO Optimizasyonu | GZL Teknoloji', 'PHP haber portalında kapsamlı SEO & GEO optimizasyonu. Lighthouse 4 kategoride 100/100, GEO skoru 35→74. JSON-LD NewsArticle şeması, llms.txt, IndexNow, AI tarayıcı erişimi (%95) ve featured image alt text sistemi hayata geçirildi. Wiribu.de (Almanya', '2026-06-11 20:51:13.000', '2026-06-11 20:51:13.000'),
  ('40000001-0000-4000-8000-000000000011', '40000000-0000-4000-8000-000000000011', 'tr', 'Bereket Fide — Kurumsal Web Sitesi & Ürün Kataloğu', 'bereket-fide-kurumsal-web-sitesi-urun-katalogu', 'Fide üretim firması için Next.js 16, Fastify ve MySQL ile full-stack kurumsal site geliştirdim. Ürün kataloğu, admin paneli, SEO uyumlu dinamik sayfalar, iletişim formu ve responsive tasarım içerir. Tailwind CSS v4 ile modern, doğal tonlarda UI.', '{"html":"<p>Fide üretim firması için Next.js 16, Fastify ve MySQL ile full-stack kurumsal site geliştirdim. Ürün kataloğu, admin paneli, SEO uyumlu dinamik sayfalar, iletişim formu ve responsive tasarım içerir. Tailwind CSS v4 ile modern, doğal tonlarda UI.</p>","description":"Fide üretim firması için Next.js 16, Fastify ve MySQL ile full-stack kurumsal site geliştirdim. Ürün kataloğu, admin paneli, SEO uyumlu dinamik sayfalar, iletişim formu ve responsive tasarım içerir. Tailwind CSS v4 ile modern, doğal tonlarda UI.","key_features":["Web Yazılım","Admin panel ve yönetilebilir içerik","SEO/GEO uyumlu yapı"],"technologies_used":["Next.js","Fastify","MySQL"],"design_highlights":["Responsive arayüz","Performans odaklı kurulum"]}', 'Bereket Fide — Kurumsal Web Sitesi & Ürün Kataloğu', 'Bereket Fide — Kurumsal Web Sitesi & Ürün Kataloğu | GZL Teknoloji', 'Fide üretim firması için Next.js 16, Fastify ve MySQL ile full-stack kurumsal site geliştirdim. Ürün kataloğu, admin paneli, SEO uyumlu dinamik sayfalar, iletişim formu ve responsive tasarım içerir. Tailwind CSS v4 ile modern, doğal tonlarda UI.', '2026-06-11 20:51:13.000', '2026-06-11 20:51:13.000'),
  ('40000001-0000-4000-8000-000000000012', '40000000-0000-4000-8000-000000000012', 'tr', 'Vista İnşaat — Kurumsal Web Sitesi & Admin Paneli', 'vista-insaat-kurumsal-web-sitesi-admin-paneli', 'İnşaat firması için Next.js 16 + Fastify + MySQL ile full-stack kurumsal site. Admin panel, çok dilli içerik yönetimi (TR/EN), teklif modülü, PDF oluşturma, galeri, SEO optimizasyonu, Cloudinary entegrasyonu. Canlı: vistainsaat.com', '{"html":"<p>İnşaat firması için Next.js 16 + Fastify + MySQL ile full-stack kurumsal site. Admin panel, çok dilli içerik yönetimi (TR/EN), teklif modülü, PDF oluşturma, galeri, SEO optimizasyonu, Cloudinary entegrasyonu. Canlı: vistainsaat.com</p>","description":"İnşaat firması için Next.js 16 + Fastify + MySQL ile full-stack kurumsal site. Admin panel, çok dilli içerik yönetimi (TR/EN), teklif modülü, PDF oluşturma, galeri, SEO optimizasyonu, Cloudinary entegrasyonu. Canlı: vistainsaat.com","key_features":["Web Yazılım","Admin panel ve yönetilebilir içerik","SEO/GEO uyumlu yapı"],"technologies_used":["Next.js","Fastify","MySQL"],"design_highlights":["Responsive arayüz","Performans odaklı kurulum"]}', 'Vista İnşaat — Kurumsal Web Sitesi & Admin Paneli', 'Vista İnşaat — Kurumsal Web Sitesi & Admin Paneli | GZL Teknoloji', 'İnşaat firması için Next.js 16 + Fastify + MySQL ile full-stack kurumsal site. Admin panel, çok dilli içerik yönetimi (TR/EN), teklif modülü, PDF oluşturma, galeri, SEO optimizasyonu, Cloudinary entegrasyonu. Canlı: vistainsaat.com', '2026-06-11 20:51:13.000', '2026-06-11 20:51:13.000'),
  ('40000001-0000-4000-8000-000000000013', '40000000-0000-4000-8000-000000000013', 'tr', 'König Energetik – Randevulu Masaj & Wellness Sitesi', 'konig-energetik-randevulu-masaj-wellness-sitesi', 'Bonn''da faaliyet gösteren bir masaj merkezi için çok dilli (TR/DE) kurumsal web sitesi geliştirdim. Online randevu sistemi, yapay zeka destekli sohbet botu ve servis yönetimi içermektedir.', '{"html":"<p>Bonn''da faaliyet gösteren bir masaj merkezi için çok dilli (TR/DE) kurumsal web sitesi geliştirdim. Online randevu sistemi, yapay zeka destekli sohbet botu ve servis yönetimi içermektedir.</p>","description":"Bonn''da faaliyet gösteren bir masaj merkezi için çok dilli (TR/DE) kurumsal web sitesi geliştirdim. Online randevu sistemi, yapay zeka destekli sohbet botu ve servis yönetimi içermektedir.","key_features":["Web Yazılım","Admin panel ve yönetilebilir içerik","SEO/GEO uyumlu yapı"],"technologies_used":["Next.js","Fastify","MySQL"],"design_highlights":["Responsive arayüz","Performans odaklı kurulum"]}', 'König Energetik – Randevulu Masaj & Wellness Sitesi', 'König Energetik – Randevulu Masaj & Wellness Sitesi | GZL Teknoloji', 'Bonn''da faaliyet gösteren bir masaj merkezi için çok dilli (TR/DE) kurumsal web sitesi geliştirdim. Online randevu sistemi, yapay zeka destekli sohbet botu ve servis yönetimi içermektedir.', '2026-06-11 20:51:13.000', '2026-06-11 20:51:13.000'),
  ('40000001-0000-4000-8000-000000000014', '40000000-0000-4000-8000-000000000014', 'tr', 'Sportoonline – Spor & Outdoor E-Ticaret Platformu', 'sportoonline-spor-outdoor-e-ticaret-platformu', 'Nike, Adidas gibi markaların spor giyim, supplement ve outdoor ürünlerini listeleyen çok kategorili bir e-ticaret platformu geliştirdim. Çok dilli yapı (TR), ürün yönetimi, sepet, kupon ve mağaza sistemi içermektedir.', '{"html":"<p>Nike, Adidas gibi markaların spor giyim, supplement ve outdoor ürünlerini listeleyen çok kategorili bir e-ticaret platformu geliştirdim. Çok dilli yapı (TR), ürün yönetimi, sepet, kupon ve mağaza sistemi içermektedir.</p>","description":"Nike, Adidas gibi markaların spor giyim, supplement ve outdoor ürünlerini listeleyen çok kategorili bir e-ticaret platformu geliştirdim. Çok dilli yapı (TR), ürün yönetimi, sepet, kupon ve mağaza sistemi içermektedir.","key_features":["E-ticaret","Admin panel ve yönetilebilir içerik","SEO/GEO uyumlu yapı"],"technologies_used":["Next.js","Fastify","MySQL"],"design_highlights":["Responsive arayüz","Performans odaklı kurulum"]}', 'Sportoonline – Spor & Outdoor E-Ticaret Platformu', 'Sportoonline – Spor & Outdoor E-Ticaret Platformu | GZL Teknoloji', 'Nike, Adidas gibi markaların spor giyim, supplement ve outdoor ürünlerini listeleyen çok kategorili bir e-ticaret platformu geliştirdim. Çok dilli yapı (TR), ürün yönetimi, sepet, kupon ve mağaza sistemi içermektedir.', '2026-06-11 20:51:13.000', '2026-06-11 20:51:13.000'),
